function paint(hex) {
  if (!hex) return [];
  const r = parseInt(hex.slice(1, 3), 16) / 255;
  const g = parseInt(hex.slice(3, 5), 16) / 255;
  const b = parseInt(hex.slice(5, 7), 16) / 255;
  return [{ type: "SOLID", color: { r, g, b } }];
}

async function loadFonts() {
  const fonts = await figma.listAvailableFontsAsync();
  const weights = {
    Regular: ["Regular"],
    Medium: ["Medium", "Regular"],
    "Semi Bold": ["Semi Bold", "SemiBold", "Bold"],
    Bold: ["Bold"],
  };
  return Object.fromEntries(await Promise.all(Object.entries(weights).map(async ([weight, choices]) => {
    const matches = choices.map(style => fonts.find(({ fontName }) =>
      fontName.family === "Inter" && fontName.style === style));
    const match = matches.find(Boolean);
    if (!match) throw new Error("Inter is required for the BarnBuddy mockups.");
    await figma.loadFontAsync(match.fontName);
    return [weight, match.fontName];
  })));
}

function buildLayer(parent, spec, fonts) {
  let node;
  if (spec.kind === "group") {
    node = figma.createFrame();
    node.resize(spec.w, spec.h);
    node.fills = [];
    node.clipsContent = false;
    for (const child of spec.children) buildLayer(node, child, fonts);
  } else if (spec.kind === "box") {
    node = figma.createRectangle();
    node.resize(spec.w, spec.h);
    node.cornerRadius = spec.radius;
    node.fills = paint(spec.fill);
    if (spec.stroke) {
      node.strokes = paint(spec.stroke);
      node.strokeAlign = "CENTER";
    }
  } else if (spec.kind === "text") {
    node = figma.createText();
    node.fontName = fonts[spec.style];
    node.fontSize = spec.size;
    node.letterSpacing = { unit: "PIXELS", value: spec.tracking };
    node.lineHeight = { unit: "PIXELS", value: spec.h };
    node.characters = spec.label;
    node.fills = paint(spec.fill);
    node.textAutoResize = "NONE";
    node.resize(spec.w, spec.h);
    node.textAlignHorizontal = spec.align.toUpperCase();
    node.textAlignVertical = "CENTER";
  } else if (spec.kind === "svg") {
    node = figma.createNodeFromSvg(spec.markup);
  } else {
    throw new Error("Unexpected layer type: " + spec.kind);
  }

  if (typeof spec.opacity === "number") node.opacity = spec.opacity;
  parent.appendChild(node);
  node.name = spec.name;
  node.x = spec.x;
  node.y = spec.y;
}

async function importMockups() {
  const fonts = await loadFonts();
  const returnPage = figma.currentPage;
  const createdPages = [];
  let firstFrames = [];
  try {
    for (const spec of layoutPages) {
      const page = figma.createPage();
      page.name = "BB " + spec.name;
      createdPages.push(page);
      await figma.setCurrentPageAsync(page);
      const frames = spec.frames.map((model, index) => {
        const frame = figma.createFrame();
        frame.name = model.name;
        frame.resize(model.w, model.h);
        frame.cornerRadius = 21;
        frame.clipsContent = true;
        frame.fills = paint(model.fill);
        frame.x = (index % 4) * (model.w + 48);
        frame.y = Math.floor(index / 4) * (model.h + 80);
        for (const layer of model.children) buildLayer(frame, layer, fonts);
        return frame;
      });
      if (createdPages.length === 1) firstFrames = frames.slice(0, 4);
    }
    await figma.setCurrentPageAsync(createdPages[0]);
    figma.currentPage.selection = firstFrames;
    figma.viewport.scrollAndZoomIntoView(firstFrames);
  } catch (error) {
    await figma.setCurrentPageAsync(returnPage);
    for (const page of createdPages.reverse()) page.remove();
    throw error;
  }
}

importMockups().then(
  () => figma.closePlugin("Imported both themes of the BarnBuddy mobile mockups."),
  error => figma.closePlugin("BarnBuddy import could not complete. " + error.message)
);
